// Pull the last 3 days, not just yesterday: Meta revises recent numbers for ~72 hours.
// The upsert below overwrites those days, so re-runs never double count.
const out = [];
for (const page of $input.all()) for (const r of page.json.data || []) {
  const act = k => Number((r.actions || []).find(a => a.action_type === k)?.value || 0);
  out.push({ json: {
    stat_date: r.date_start, creative_id: r.ad_id, spend: Number(r.spend),
    impressions: Number(r.impressions), clicks: Number(r.inline_link_clicks || 0),
    frequency_7d: Number(r.frequency), lp_views: act('landing_page_view')
  } });
}
if (!out.length) throw new Error('Meta returned no rows. Check token and ad account.');
return out;
